let raw = msg.payload;
if (typeof raw === 'string') {
    try {
        raw = JSON.parse(raw);
    } catch (err) {
        node.warn('JSON invalide ignore: ' + err.message);
        return null;
    }
}

if (!raw || typeof raw !== 'object') {
    return null;
}

// Mappage standard des capteurs Wokwi vers les noms de features ML
let sensor_data = {
    temperature_c: Number(raw.temperature !== undefined ? raw.temperature : 25.0),
    pressure_hpa: Number(raw.pressure !== undefined ? raw.pressure : 1013.0),
    humidity_pct: Number(raw.humidity !== undefined ? raw.humidity : 50.0),
    altitude_m: Number(raw.altitude !== undefined ? raw.altitude : 0.0),
    vibration_x_ms2: Number(raw.accX !== undefined ? raw.accX : 0.0),
    vibration_y_ms2: Number(raw.accY !== undefined ? raw.accY : 0.0),
    vibration_z_ms2: Number(raw.accZ !== undefined ? raw.accZ : 9.8),
    vibration_norm_ms2: Math.sqrt(Math.pow(raw.accX || 0, 2) + Math.pow(raw.accY || 0, 2) + Math.pow((raw.accZ || 9.8) - 9.8, 2)),
    rpm: Number(raw.potentiometer !== undefined ? raw.potentiometer * 60 : 1500.0),
    voltage_v: 3.3,
    current_a: 0.85,
    power_w: 2.8,
    operating_hours: 1200,
    load_pct: Number(raw.potentiometer !== undefined ? raw.potentiometer : 50)
};

msg.sensor_data = sensor_data;
msg.payload = sensor_data;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

let ml = msg.payload || {};
let s = msg.sensor_data || {};

// Format Point InfluxDB
msg.payload = [{
    measurement: 'sensors_ml',
    fields: {
        temperature_c: s.temperature_c,
        pressure_hpa: s.pressure_hpa,
        humidity_pct: s.humidity_pct,
        altitude_m: s.altitude_m,
        vibration_norm_ms2: s.vibration_norm_ms2,
        rpm: s.rpm,
        voltage_v: s.voltage_v,
        current_a: s.current_a,
        power_w: s.power_w,
        ml_anomaly: ml.anomaly !== undefined ? Number(ml.anomaly) : 0,
        ml_anomaly_score: ml.anomaly_score !== undefined ? Number(ml.anomaly_score) : 0.15,
        ml_threshold: ml.threshold !== undefined ? Number(ml.threshold) : 0.5244,
        ml_status: ml.status || (ml.anomaly === 1 ? 'ANOMALY' : 'NORMAL')
    },
    tags: {
        device: 'ESP32_Wokwi',
        model: ml.model || 'IsolationForest_v2'
    },
    timestamp: Date.now()
}];

return msg;

let s = msg.sensor_data || {};
msg.payload = [{
    measurement: 'sensors_ml',
    fields: {
        temperature_c: s.temperature_c,
        pressure_hpa: s.pressure_hpa,
        humidity_pct: s.humidity_pct,
        altitude_m: s.altitude_m,
        vibration_norm_ms2: s.vibration_norm_ms2,
        rpm: s.rpm,
        voltage_v: s.voltage_v,
        current_a: s.current_a,
        power_w: s.power_w,
        ml_anomaly: 0,
        ml_anomaly_score: 0.0,
        ml_status: 'API_WAITING'
    },
    tags: {
        device: 'ESP32_Wokwi'
    },
    timestamp: Date.now()
}];
return msg;
